//! The `quip/twisted-ice-dimer` family, revision 1: twisted ice with local tile
//! gauges, a weak signed layer, and disjoint ferromagnetic pairs.
//!
//! The construction picks a set of ice tiles. Each tile carries its own local
//! gauge, so a node that sits in two tiles has two gauges. A tile edge gets
//! the strong coupling [`STRONG_MILLI`] twisted by the gauges of its own tile.
//! Every other edge gets a random coupling of magnitude `weak_milli`, and
//! `pairs` node-disjoint non-tile edges get the ferromagnetic coupling
//! [`PAIR_MILLI`]. The research cohort is not regenerated by this revision.

use alloc::vec;
use alloc::vec::Vec;
use core::num::NonZeroU32;

use crate::descriptor::{Contract, FieldSpec, Params, SizeBounds, TopologyStats, Value, ValueType};
use crate::family::{BaseTopology, Construction, InstanceBody, Streams};
use crate::ice::build::{
    gauges_payload, lattice, mark_tiles, parse_gauges, parse_tiles, region, sections, select_tiles,
    sorted_edges, tiles_payload, topology_bounds, Reader,
};
use crate::ice::{candidates, StructureError, STRONG_MILLI};
use crate::instance::{Instance, InstanceLimits};
use crate::rng::{shuffle, uniform};
use crate::Code;

/// The pair coupling, in milli.
pub const PAIR_MILLI: i32 = -1000;

/// The parameters of `quip/twisted-ice-dimer@1`.
pub const TWISTED_DIMER_SCHEMA: &[FieldSpec] = &[
    FieldSpec {
        tag: 1,
        kind: ValueType::U16,
        min: 0,
        max: 32,
    },
    FieldSpec {
        tag: 2,
        kind: ValueType::U8,
        min: 0,
        max: 8,
    },
    FieldSpec {
        tag: 3,
        kind: ValueType::U16,
        min: 1,
        max: 999,
    },
    FieldSpec {
        tag: 4,
        kind: ValueType::U32,
        min: 0,
        max: 65_536,
    },
];

/// Tag of the weak coupling magnitude parameter.
const TAG_WEAK: u16 = 3;
/// Tag of the pair count parameter.
const TAG_PAIRS: u16 = 4;
/// Metadata kind of the tile list.
const KIND_TILES: u16 = 1;
/// Metadata kind of the local gauges.
const KIND_GAUGES: u16 = 2;
/// Metadata kind of the pair list.
const KIND_PAIRS: u16 = 3;

/// The stream that orders the left spine edges.
const LEFT: &str = "left";
/// The stream that orders the right spine edges.
const RIGHT: &str = "right";
/// The stream that draws the local gauges.
const GAUGE: &str = "gauge";
/// The stream that draws the weak signs.
const WEAK: &str = "weak";
/// The stream that shuffles the pair candidates.
const DIMER: &str = "dimer";

const LIMITS: InstanceLimits = match InstanceLimits::new(131_072, 2_097_152, 1_000, 0, 8_388_608) {
    Some(limits) => limits,
    None => InstanceLimits::FAM_37,
};

/// The construction of `quip/twisted-ice-dimer@1`. Its streams are `left`,
/// `right`, `gauge`, `weak`, and `dimer`.
pub static TWISTED_DIMER: Construction = Construction {
    labels: &[LEFT, RIGHT, GAUGE, WEAK, DIMER],
    check_topology,
    generate,
    check_metadata,
};

/// The contract of `quip/twisted-ice-dimer@1`.
pub const TWISTED_DIMER_V1: Contract = Contract {
    family_id: "quip/twisted-ice-dimer",
    revision: 1,
    schema: TWISTED_DIMER_SCHEMA,
    metadata_kinds: &[KIND_TILES, KIND_GAUGES, KIND_PAIRS],
    limits: LIMITS,
    size_bounds: twisted_dimer_size_bounds,
    construction: Some(&TWISTED_DIMER),
};

/// One named parameter set.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Recipe {
    /// The short name of the recipe.
    pub alias: &'static str,
    /// The cell the recipe belongs to.
    pub cell: &'static str,
    /// The canonical parameter bytes.
    pub params: &'static [u8],
}

