/// The sizes of an instance: the topology itself.
fn twisted_dimer_size_bounds(_: &Params<'_>, stats: &TopologyStats) -> Result<SizeBounds, Code> {
    topology_bounds(stats)
}

/// The weak magnitude, `None` when the parameter is missing or out of range.
fn weak_milli(params: &Params<'_>) -> Option<i32> {
    match params.get(TAG_WEAK) {
        Some(Value::Unsigned(weak)) => i32::try_from(weak).ok(),
        _ => None,
    }
}

/// The pair count, `None` when the parameter is missing or out of range.
fn pair_count(params: &Params<'_>) -> Option<usize> {
    match params.get(TAG_PAIRS) {
        Some(Value::Unsigned(pairs)) => usize::try_from(pairs).ok(),
        _ => None,
    }
}

/// Admission: the parameters name a lattice, the topology carries tiles, and
/// no more pairs are asked for than half the nodes. A degree above the limit
/// is left to the size bounds (code 13).
fn check_topology(params: &Params<'_>, topology: &BaseTopology) -> bool {
    let Ok(lattice) = lattice(params) else {
        return false;
    };
    match candidates(lattice, topology) {
        Ok(_) | Err(StructureError::DegreeAboveLimit) => {}
        Err(_) => return false,
    }
    pair_count(params).is_some_and(|pairs| pairs <= topology.node_ids().len() / 2)
}

/// A pair taken by the walk: the edge position and the edge.
type ChosenPair = (usize, (u32, u32));

/// The tiles and the local gauges of an instance.
pub type TileGauges = (Vec<[u32; 4]>, Vec<[i8; 4]>);

/// The six edges of a tile with their strong couplings under the tile's own
/// gauge: `STRONG_MILLI * g[a] * g[b]`. `None` when the arithmetic overflows.
fn tile_couplings(nodes: [u32; 4], gauge: [i8; 4]) -> Option<[((u32, u32), i32); 6]> {
    let [a, b, c, d] = nodes;
    let [ga, gb, gc, gd] = gauge;
    let coupling = |x: i8, y: i8| {
        STRONG_MILLI
            .checked_mul(i32::from(x))?
            .checked_mul(i32::from(y))
    };
    Some([
        ((a, b), coupling(ga, gb)?),
        ((a, c), coupling(ga, gc)?),
        ((a, d), coupling(ga, gd)?),
        ((b, c), coupling(gb, gc)?),
        ((b, d), coupling(gb, gd)?),
        ((c, d), coupling(gc, gd)?),
    ])
}

fn generate(
    params: &Params<'_>,
    topology: &BaseTopology,
    streams: &mut Streams<'_>,
) -> Result<InstanceBody, Code> {
    let defect = Code::TopologyIncompatible;
    let weak = weak_milli(params).ok_or(Code::ParamsMalformed)?;
    let pairs = pair_count(params).ok_or(Code::ParamsMalformed)?;
    let lattice = lattice(params).map_err(|_| defect)?;
    let tiles = select_tiles(lattice, topology, streams, LEFT, RIGHT)?;

    let two = NonZeroU32::MIN.saturating_add(1);
    let mut gauge_stream = streams.open(GAUGE).ok_or(Code::NoInstance)?;
    let gauges: Vec<[i8; 4]> = tiles
        .iter()
        .map(|_| {
            [(); 4].map(|()| {
                if uniform(&mut gauge_stream, two) == 0 {
                    1
                } else {
                    -1
                }
            })
        })
        .collect();

    let node_ids = topology.node_ids().to_vec();
    let edges = sorted_edges(topology);
    let mut strong: Vec<Option<i32>> = vec![None; edges.len()];
    for (tile, gauge) in tiles.iter().zip(&gauges) {
        for (pair, coupling) in tile_couplings(tile.nodes, *gauge).ok_or(Code::BoundsExceeded)? {
            let at = edges.binary_search(&pair).map_err(|_| defect)?;
            *strong.get_mut(at).ok_or(defect)? = Some(coupling);
        }
    }

    let mut weak_stream = streams.open(WEAK).ok_or(Code::NoInstance)?;
    let mut j: Vec<i32> = Vec::with_capacity(edges.len());
    for fixed in &strong {
        j.push(match fixed {
            Some(coupling) => *coupling,
            None if uniform(&mut weak_stream, two) == 0 => weak,
            None => -weak,
        });
    }

    let chosen = choose_pairs(streams, &edges, &strong, node_ids.len(), pairs)?;
    for &(at, _) in &chosen {
        *j.get_mut(at).ok_or(defect)? = PAIR_MILLI;
    }
    let mut pair_edges: Vec<(u32, u32)> = chosen.iter().map(|&(_, edge)| edge).collect();
    pair_edges.sort_unstable();

    let metadata = metadata_region(&tiles_payload(&tiles)?, &gauges, &pair_edges)?;
    Ok(InstanceBody {
        h: vec![0; node_ids.len()],
        node_ids,
        edges,
        j,
        offset_milli: 0,
        metadata,
    })
}

/// Shuffle the non-tile edges on the `dimer` stream and walk the result,
/// taking each edge whose ends are both free. The shuffle runs also when
/// `pairs` is zero. Returns `(edge position, edge)` for each pair taken.
///
/// # Errors
///
/// [`Code::NoInstance`] when fewer than `pairs` edges can be taken.
fn choose_pairs(
    streams: &mut Streams<'_>,
    edges: &[(u32, u32)],
    strong: &[Option<i32>],
    n: usize,
    pairs: usize,
) -> Result<Vec<ChosenPair>, Code> {
    let mut order: Vec<u32> = Vec::new();
    for (at, fixed) in strong.iter().enumerate() {
        if fixed.is_none() {
            order.push(u32::try_from(at).map_err(|_| Code::BoundsExceeded)?);
        }
    }
    let mut rng = streams.open(DIMER).ok_or(Code::NoInstance)?;
    shuffle(&mut rng, &mut order)?;

    let defect = Code::TopologyIncompatible;
    let mut used = vec![false; n];
    let mut chosen: Vec<ChosenPair> = Vec::new();
    for at in order {
        if chosen.len() >= pairs {
            break;
        }
        let at = usize::try_from(at).map_err(|_| Code::BoundsExceeded)?;
        let (u, v) = *edges.get(at).ok_or(defect)?;
        let pos_u = usize::try_from(u).map_err(|_| Code::BoundsExceeded)?;
        let pos_v = usize::try_from(v).map_err(|_| Code::BoundsExceeded)?;
        if *used.get(pos_u).ok_or(defect)? || *used.get(pos_v).ok_or(defect)? {
            continue;
        }
        *used.get_mut(pos_u).ok_or(defect)? = true;
        *used.get_mut(pos_v).ok_or(defect)? = true;
        chosen.push((at, (u, v)));
    }
    if chosen.len() < pairs {
        return Err(Code::NoInstance);
    }
    Ok(chosen)
}

/// The metadata region: tiles (kind 1), local gauges (kind 2), pairs (kind 3).
fn metadata_region(
    tiles: &[u8],
    gauges: &[[i8; 4]],
    pairs: &[(u32, u32)],
) -> Result<Vec<u8>, Code> {
    let mut pair_payload = u32::try_from(pairs.len())
        .map_err(|_| Code::BoundsExceeded)?
        .to_le_bytes()
        .to_vec();
    for &(a, b) in pairs {
        pair_payload.extend_from_slice(&a.to_le_bytes());
        pair_payload.extend_from_slice(&b.to_le_bytes());
    }
    region(&[
        (KIND_TILES, tiles.to_vec()),
        (KIND_GAUGES, gauges_payload(gauges)?),
        (KIND_PAIRS, pair_payload),
    ])
}

/// The pairs of a kind 3 payload: ascending, distinct, `a < b < n`.
fn parse_pairs(payload: &[u8], n: usize) -> Option<Vec<(u32, u32)>> {
    let mut reader = Reader::new(payload);
    let count = usize::try_from(reader.u32()?).ok()?;
    if reader.rest().len() != count.checked_mul(8)? {
        return None;
    }
    let mut pairs: Vec<(u32, u32)> = Vec::with_capacity(count);
    for _ in 0..count {
        let pair = (reader.u32()?, reader.u32()?);
        let in_range = pair.0 < pair.1 && usize::try_from(pair.1).ok()? < n;
        if !in_range || pairs.last().is_some_and(|prev| *prev >= pair) {
            return None;
        }
        pairs.push(pair);
    }
    Some(pairs)
}

/// The tiles and local gauges of a generated instance, for diagnostics and
/// tests. `None` for a malformed region. This is not part of the metadata
/// check.
#[must_use]
pub fn local_gauges(instance: &Instance) -> Option<TileGauges> {
    let n = instance.node_ids().len();
    let [tile_payload, gauge_payload, _] =
        sections(instance.metadata(), [KIND_TILES, KIND_GAUGES, KIND_PAIRS])?;
    let tiles = parse_tiles(tile_payload, n)?;
    let gauges = parse_gauges(gauge_payload, tiles.len())?;
    Some((tiles, gauges))
}

fn check_metadata(params: &Params<'_>, instance: &Instance) -> bool {
    check_instance(params, instance).is_some()
}

/// `Some` when the instance is a valid twisted-ice-dimer instance.
fn check_instance(params: &Params<'_>, instance: &Instance) -> Option<()> {
    let weak = weak_milli(params)?;
    let want_pairs = pair_count(params)?;
    let n = instance.node_ids().len();
    let [tile_payload, gauge_payload, pair_payload] =
        sections(instance.metadata(), [KIND_TILES, KIND_GAUGES, KIND_PAIRS])?;
    let tiles = parse_tiles(tile_payload, n)?;
    let gauges = parse_gauges(gauge_payload, tiles.len())?;
    let pairs = parse_pairs(pair_payload, n)?;
    if pairs.len() != want_pairs {
        return None;
    }
    let edges = instance.edges();
    let js = instance.j();

    let all_zero = instance.h().iter().all(|&h| h == 0) && instance.offset_milli() == 0;
    if !all_zero || js.len() != edges.len() {
        return None;
    }

    let mut is_tile = mark_tiles(&tiles, edges, n)?;
    for (tile, gauge) in tiles.iter().zip(&gauges) {
        for (pair, coupling) in tile_couplings(*tile, *gauge)? {
            let at = edges.binary_search(&pair).ok()?;
            if *js.get(at)? != coupling {
                return None;
            }
        }
    }

    let mut taken = vec![false; n];
    for pair in &pairs {
        let at = edges.binary_search(pair).ok()?;
        let tile_edge = is_tile.get_mut(at)?;
        if *tile_edge || *js.get(at)? != PAIR_MILLI {
            return None;
        }
        // A pair edge is not a tile edge, so this flag marks it as taken.
        *tile_edge = true;
        for end in [pair.0, pair.1] {
            let node = taken.get_mut(usize::try_from(end).ok()?)?;
            if *node {
                return None;
            }
            *node = true;
        }
    }

    // Tile edges and pair edges are both flagged now. The others are weak.
    // The tile and pair edges were checked above, so a flagged edge is done.
    for (&flagged, &coupling) in is_tile.iter().zip(js) {
        if !flagged && coupling != weak && coupling != -weak {
            return None;
        }
    }
    Some(())
}
